resources.ui/style.css:
:root{color-scheme:light dark;--surface:#fff;--onSurface:#222;--surfaceContainer:#eee;--primary:#446;--onPrimary:#fff;--outline:#999}*{box-sizing:border-box}html,body{margin:0;font:15px system-ui,sans-serif;background:var(--surface);color:var(--onSurface)}body{position:fixed;inset:0;display:flex;flex-direction:column;overflow:hidden}main{flex:1;min-height:0;overflow:auto;overflow-wrap:anywhere;padding:16px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;gap:12px}main>*{grid-column:1/-1}.card{grid-column:auto;border:1px solid var(--outline);border-radius:16px;padding:12px}.card button{width:100%}.caption{font-size:12px;opacity:.7}.title{font-size:20px;font-weight:600}p{white-space:pre-wrap;line-height:1.5;margin:8px 0}footer{flex-shrink:0;display:flex;flex-wrap:wrap;gap:8px;padding:12px;border-top:1px solid var(--outline)}button,input,textarea,select{font:inherit;color:inherit}button{border:0;border-radius:12px;background:var(--surfaceContainer);padding:10px 14px}button:disabled{opacity:.45}footer button:last-child{background:var(--primary);color:var(--onPrimary)}label{display:block;font-size:13px}input,textarea{display:block;width:100%;border:1px solid var(--outline);border-radius:12px;padding:12px;margin-top:8px;background:var(--surface)}textarea{min-height:250px;font-family:monospace;resize:vertical}input:focus,textarea:focus,button:focus-visible{outline:2px solid var(--primary)}@media(min-width:600px){main{grid-template-columns:repeat(3,minmax(0,1fr))}}

main.editing{display:flex;flex-direction:column;gap:8px;overflow:hidden;padding:10px}main.editing label{flex-shrink:0}main.editing label input{padding:8px;margin-top:4px}.editor-toolbar{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-shrink:0;font-size:12px}.editor-toolbar button{padding:6px 12px}#code-editor{flex:1;min-height:120px;overflow:hidden;border:1px solid var(--outline);border-radius:10px}.cm-editor{min-height:100%;max-height:100%}.cm-content{padding-bottom:24px}.cm-editor.cm-focused{outline:1px solid var(--primary)}.cm-tooltip{z-index:20}

#workbench{display:flex;flex:1;min-height:0;position:relative}#file-tree{width:260px;flex-shrink:0;overflow:auto;background:var(--surfaceContainer);border-inline-end:1px solid var(--outline)}#file-tree[hidden]{display:none}#file-tree header{display:flex;align-items:center;justify-content:space-between;padding:12px;position:sticky;top:0;background:var(--surfaceContainer);z-index:1}.file-tree-row{display:flex;align-items:center;min-height:40px}.file-tree-row.selected{background:var(--surface)}.tree-entry{min-width:0;text-align:start;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;background:transparent;border-radius:0;padding:8px 4px}.tree-expand,.tree-spacer{width:28px;flex-shrink:0;text-align:center;padding:6px;background:transparent}.tree-more{font-size:12px;margin:4px 12px}#tree-toggle{display:none}@media(max-width:839px){#file-tree{display:none;position:absolute;inset:0 auto 0 0;width:min(82vw,340px);z-index:10;box-shadow:4px 0 20px #0002}#file-tree.open:not([hidden]){display:block}#tree-toggle{display:block;align-self:flex-start;padding:6px 12px;flex-shrink:0}}

.tree-close{display:none}#file-tree header strong{flex:1}#file-tree header button{padding:6px 10px}@media(max-width:839px){.tree-close{display:block}}

main.git-diff{display:flex;flex-direction:column;overflow:hidden;gap:12px}main.git-diff>p{flex-shrink:0}#git-patch{flex:1;min-height:160px;min-width:0;margin:0;white-space:pre;overflow:auto;overscroll-behavior:contain;font:13px/1.6 monospace;border:1px solid var(--outline);border-radius:10px;padding:12px}.git-protocol{display:none}

.row{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
